-- =============================================================================
-- PERSONAS + KNOWLEDGE BASES - Safe Version (handles existing data)
-- =============================================================================
-- Uses ON CONFLICT DO NOTHING to skip existing rows
-- =============================================================================

-- Create knowledge_bases table if not exists
CREATE TABLE IF NOT EXISTS "knowledge_bases" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kb_slug" TEXT UNIQUE NOT NULL,
  "kb_name" TEXT NOT NULL,
  "kb_description" TEXT,
  "kb_type" TEXT,
  "paradigm_family" TEXT,
  "cultural_origin" TEXT,
  "era" TEXT,
  "is_system" BOOLEAN DEFAULT TRUE,
  "is_public" BOOLEAN DEFAULT TRUE,
  "requires_training" BOOLEAN DEFAULT FALSE,
  "maturity_gate" TEXT,
  "primary_topics" TEXT,
  "language_register" TEXT,
  "evidence_level" TEXT,
  "contraindication_tags" TEXT,
  "requires_disclaimer" BOOLEAN DEFAULT FALSE,
  "disclaimer_text" TEXT,
  "icon" TEXT,
  "sort_order" INTEGER DEFAULT 100,
  "is_active" BOOLEAN DEFAULT TRUE,
  "notes" TEXT,
  "created_at" TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "user_knowledge_access" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" TEXT NOT NULL,
  "kb_id" BIGINT REFERENCES "knowledge_bases"("id"),
  "access_level" TEXT DEFAULT 'read',
  "granted_at" TIMESTAMPTZ DEFAULT NOW(),
  "granted_by" TEXT,
  "notes" TEXT,
  UNIQUE("user_id", "kb_id")
);

CREATE TABLE IF NOT EXISTS "programme_knowledge_map" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "programme_profile_id" TEXT NOT NULL,
  "kb_id" BIGINT REFERENCES "knowledge_bases"("id"),
  "is_required" BOOLEAN DEFAULT FALSE,
  "is_default" BOOLEAN DEFAULT TRUE,
  "weight" INTEGER DEFAULT 50,
  UNIQUE("programme_profile_id", "kb_id")
);

CREATE TABLE IF NOT EXISTS "persona_lens_compatibility" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "persona_id" BIGINT,
  "lens_id" BIGINT,
  "compatibility_score" INTEGER DEFAULT 50,
  "notes" TEXT
);

CREATE TABLE IF NOT EXISTS "persona_kb_compatibility" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "persona_id" BIGINT,
  "kb_id" BIGINT,
  "compatibility_score" INTEGER DEFAULT 50,
  "notes" TEXT
);

