-- Add columns to user_lens_context if they don't exist
DO $$ 
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'user_lens_context' AND column_name = 'suggested_persona') THEN
    ALTER TABLE "user_lens_context" ADD COLUMN "suggested_persona" TEXT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'user_lens_context' AND column_name = 'suggested_kb') THEN
    ALTER TABLE "user_lens_context" ADD COLUMN "suggested_kb" TEXT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'user_lens_context' AND column_name = 'persona_reasoning') THEN
    ALTER TABLE "user_lens_context" ADD COLUMN "persona_reasoning" TEXT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'user_lens_context' AND column_name = 'kb_reasoning') THEN
    ALTER TABLE "user_lens_context" ADD COLUMN "kb_reasoning" TEXT;
  END IF;
END $$;

-- Create indexes
CREATE INDEX IF NOT EXISTS "idx_kb_slug" ON "knowledge_bases" ("kb_slug");
CREATE INDEX IF NOT EXISTS "idx_kb_type" ON "knowledge_bases" ("kb_type");
CREATE INDEX IF NOT EXISTS "idx_kb_paradigm" ON "knowledge_bases" ("paradigm_family");
CREATE INDEX IF NOT EXISTS "idx_user_kb_user" ON "user_knowledge_access" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_prog_kb_prog" ON "programme_knowledge_map" ("programme_profile_id");

-- Success message
SELECT 'Personas and Knowledge Bases updated. ' || 
       (SELECT COUNT(*) FROM knowledge_bases) || ' knowledge bases, ' ||
       (SELECT COUNT(*) FROM archetypal_personas) || ' personas.' AS status;




